function makeJWT(payload: Record<string, unknown>): string {
  const b64url = (o: object): string => Buffer.from(JSON.stringify(o)).toString("base64url");
  return `${b64url({ alg: "HS256", typ: "JWT" })}.${b64url(payload)}.signature`;
}

const inFiveMinutes = (): number => Math.floor(Date.now() / 1000) + 300;
const fiveMinutesAgo = (): number => Math.floor(Date.now() / 1000) - 300;

export { fiveMinutesAgo, inFiveMinutes, makeJWT };
